export function isSameParameter(left, right) {
    if (left.in !== right.in) {
        return false;
    }
    if (left.in === 'header' &&
        typeof left.name === 'string' &&
        typeof right.name === 'string') {
        return left.name.toLowerCase() === right.name.toLowerCase();
    }
    return left.name === right.name;
}
